        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'mean': 13.0, 'max': 13, 'label': 'ALPHA'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 7.0, 'max': 8, 'label': 'ALPHA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 5.0, 'max': 5, 'label': 'ALPHA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 5.0, 'max': 5, 'label': 'ALPHA'})
